<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { MainMenuContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: MainMenuContract & { embedded?:boolean; hideMobileTrigger?:boolean } = $props();
import Modal from './Modal.svelte';const uid=$props.id();let narrow=$state(false);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});const expanded=control<string|null>(()=>p.expandedId,untrack(()=>p.defaultExpandedId),null,id=>p.onExpandedChange?.({id}));const mobile=control(()=>p.mobileOpen,untrack(()=>p.defaultMobileOpen),false,open=>p.onMobileOpenChange?.({open}));let root=$state<HTMLElement>();
function pathTo(items:typeof p.items,id:string|null):string[]{for(const item of items){if(item.id===id)return[item.id];const rest=item.children?pathTo(item.children,id):[];if(rest.length)return[item.id,...rest];}return[];}
const path=$derived(pathTo(p.items,expanded.value));
function active(id:string){return path.includes(id);}
function focusTrigger(id:string|undefined){[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(node=>node.getAttribute('aria-controls')===`${uid}-${id}`)?.focus();}
async function collapse(all=false){const previous=path.at(-1);const next=all?null:path.at(-2)??null;expanded.request(next);await tick();if(expanded.value===next)focusTrigger(all?pathTo(p.items,previous??null)[0]:previous);}
function escape(e:KeyboardEvent){if(!ignoredKey(e)&&e.key==='Escape'&&expanded.value){e.preventDefault();e.stopPropagation();void collapse(true);}}
</script>
{#snippet list(items:typeof p.items,level:number)}<ul {...owned('main-menu',level===1?'list':'submenu',level>1&&'expanded')}>{#each items as item(item.id)}<li {...owned('main-menu','item',item.id===p.currentId&&'current',item.children&&(active(item.id)?'expanded':'collapsed'))}>{#if item.children}<button type="button" aria-expanded={active(item.id)} aria-current={active(item.id)?'true':undefined} aria-controls={`${uid}-${item.id}`} {...owned('main-menu','trigger',active(item.id)?'expanded':'collapsed')} onclick={()=>expanded.request(active(item.id)?pathTo(p.items,item.id).at(-2)??null:item.id)}>{item.label}<span {...owned('main-menu','indicator')} aria-hidden="true"></span></button><div id={`${uid}-${item.id}`} hidden={!active(item.id)}>{#if item.description}<p>{item.description}</p>{/if}{@render list(item.children,level+1)}</div>{:else if item.href}<a href={item.href} aria-current={item.id===p.currentId?'page':undefined} {...owned('main-menu','link',item.id===p.currentId&&'current')}>{item.label}</a>{/if}</li>{/each}</ul>{/snippet}<nav bind:this={root} aria-label={p.label??'메인 메뉴'} hidden={narrow&&!mobile.value&&p.hideMobileTrigger} {...owned('main-menu','root',expanded.value?'expanded':'collapsed',mobile.value&&'mobile-open')} onkeydown={escape}>{#if !mobile.value&&(!narrow||p.embedded)}<div class="desktop" style:display={p.embedded?'block':undefined}>{@render list(p.items,1)}</div>{/if}{#if !p.embedded&&!p.hideMobileTrigger}<button id={p.mobileTriggerId} type="button" {...owned('main-menu','mobile-trigger',mobile.value?'expanded':'collapsed')} aria-expanded={mobile.value} onclick={()=>mobile.request(true)}>{p.mobileTriggerLabel??'전체 메뉴'}</button>{/if}{#if !p.embedded}<div class="mobile-layer"><Modal title="전체 메뉴" open={mobile.value} returnFocusId={p.mobileTriggerId} onOpenChange={({open})=>mobile.request(open)}><div {...owned('main-menu','mobile-content',mobile.value&&'mobile-open')}>{#if expanded.value}<button type="button" {...owned('main-menu','back')} onclick={()=>collapse()}>이전</button>{/if}<label>메뉴 검색<input value={p.query??''} oninput={e=>p.onQueryChange?.({value:e.currentTarget.value})}/></label>{@render list(p.items,1)}</div></Modal></div>{/if}</nav><style>.desktop{display:block}[data-krds-part="mobile-trigger"]{display:none}@media(max-width:767px){.desktop{display:none}[data-krds-part="mobile-trigger"]{display:block}}</style>
